package edu.niu.android.smartstudyplanner.data.entities;

import androidx.room.Entity;
import androidx.room.PrimaryKey;

@Entity(tableName = "courses")
public class Course {

    // Auto generated primary key assigned by Room on insert.
    @PrimaryKey(autoGenerate = true)
    private long id;

    // Course name as shown in the UI, e.g. "CSCI 524: Adv Android"
    private String name;

    // Instructor's display name
    private String instructor;

    // Hex color string from the palette in ColorUtils, e.g. "#0369A1"
    private String color;

    // Meeting days and times, e.g. "MW 9:30 to 10:45 AM"
    private String schedule;

    // Building and room number where the class meets
    private String room;

    // Term this course belongs to, e.g. "Spring 2026"
    private String semester;

    // Timestamp (millis) when the course was added
    private long createdAt;

    /**
     * Builds a new Course. The id is auto generated by Room on insert,
     * so callers don't pass it in.
     */
    public Course(String name, String instructor, String color, String schedule,
                  String room, String semester, long createdAt) {
        this.name = name;
        this.instructor = instructor;
        this.color = color;
        this.schedule = schedule;
        this.room = room;
        this.semester = semester;
        this.createdAt = createdAt;
    }

    // Standard getters and setters used by Room and the UI.

    public long getId() { return id; }
    public void setId(long id) { this.id = id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getInstructor() { return instructor; }
    public void setInstructor(String instructor) { this.instructor = instructor; }

    public String getColor() { return color; }
    public void setColor(String color) { this.color = color; }

    public String getSchedule() { return schedule; }
    public void setSchedule(String schedule) { this.schedule = schedule; }

    public String getRoom() { return room; }
    public void setRoom(String room) { this.room = room; }

    public String getSemester() { return semester; }
    public void setSemester(String semester) { this.semester = semester; }

    public long getCreatedAt() { return createdAt; }
    public void setCreatedAt(long createdAt) { this.createdAt = createdAt; }
}